import java.util.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    static ListNode build(int... vals) {
        ListNode dummy = new ListNode(0), tail = dummy;
        for (int v : vals) { tail.next = new ListNode(v); tail = tail.next; }
        return dummy.next;
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder();
        for (ListNode n = head; n != null; n = n.next) {
            if (sb.length() > 0) sb.append(" -> ");
            sb.append(n.val);
        }
        return sb.length() == 0 ? "(empty)" : sb.toString();
    }

    // Iterative reversal with a trace of each step
    static ListNode reverse(ListNode head, boolean trace) {
        ListNode prev = null, curr = head;
        int step = 0;
        while (curr != null) {
            ListNode next = curr.next;   // 1. save
            curr.next = prev;            // 2. flip
            prev = curr;                 // 3. advance prev
            curr = next;                 //    advance curr
            if (trace) {
                step++;
                System.out.println(step + " | prev=" + prev.val + " curr="
                    + (curr == null ? "null" : curr.val) + " | reversed part: " + show(prev));
            }
        }
        return prev;
    }

    static ListNode reverseRecursive(ListNode head) {
        if (head == null || head.next == null) return head;
        ListNode newHead = reverseRecursive(head.next);
        head.next.next = head;
        head.next = null;
        return newHead;
    }

    // LeetCode 92: reverse positions left..right (1-indexed)
    static ListNode reverseBetween(ListNode head, int left, int right) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode before = dummy;
        for (int i = 1; i < left; i++) before = before.next;
        ListNode curr = before.next;
        for (int i = 0; i < right - left; i++) {
            ListNode moving = curr.next;     // node to move to the front of the segment
            curr.next = moving.next;
            moving.next = before.next;
            before.next = moving;
        }
        return dummy.next;
    }

    // LeetCode 25
    static ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode groupPrev = dummy;
        while (true) {
            ListNode kth = groupPrev;
            for (int i = 0; i < k && kth != null; i++) kth = kth.next;
            if (kth == null) break;                  // fewer than k nodes left
            ListNode groupNext = kth.next;
            ListNode prev = groupNext, curr = groupPrev.next;
            while (curr != groupNext) {
                ListNode nxt = curr.next;
                curr.next = prev;
                prev = curr;
                curr = nxt;
            }
            ListNode oldFirst = groupPrev.next;      // becomes the tail of the group
            groupPrev.next = kth;
            groupPrev = oldFirst;
        }
        return dummy.next;
    }

    // LeetCode 21
    static ListNode mergeTwo(ListNode a, ListNode b, boolean trace) {
        ListNode dummy = new ListNode(0), tail = dummy;
        int step = 0;
        List<Integer> out = new ArrayList<>();
        while (a != null && b != null) {
            String pick;
            if (a.val <= b.val) { out.add(a.val); tail.next = a; a = a.next; pick = "take A"; }
            else { out.add(b.val); tail.next = b; b = b.next; pick = "take B"; }
            tail = tail.next;
            if (trace) System.out.println(++step + " | a=" + (a == null ? "null" : a.val)
                + " b=" + (b == null ? "null" : b.val) + " | " + pick + " | out so far: " + out);
        }
        tail.next = (a != null) ? a : b;
        if (trace) System.out.println("end | append the rest of B | out: " + show(dummy.next));
        return dummy.next;
    }

    // LeetCode 83 using a dummy-free walk, and 203-style removal with dummy
    static ListNode removeValue(ListNode head, int target) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode curr = dummy;
        while (curr.next != null) {
            if (curr.next.val == target) curr.next = curr.next.next;
            else curr = curr.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        System.out.println("Input: " + show(build(1, 2, 3, 4, 5)));
        System.out.println("-- trace of iterative reverse --");
        System.out.println("reversed: " + show(reverse(build(1, 2, 3, 4, 5), true)));
        System.out.println("recursive: " + show(reverseRecursive(build(1, 2, 3, 4, 5))));
        System.out.println("empty: " + show(reverse(null, false)));
        System.out.println("between 2..4: " + show(reverseBetween(build(1, 2, 3, 4, 5), 2, 4)));
        System.out.println("k=2: " + show(reverseKGroup(build(1, 2, 3, 4, 5), 2)));
        System.out.println("k=3: " + show(reverseKGroup(build(1, 2, 3, 4, 5), 3)));
        System.out.println("-- trace of merge --");
        System.out.println("A: 1 -> 3 -> 5   B: 2 -> 4 -> 6 -> 8");
        System.out.println("result: " + show(mergeTwo(build(1, 3, 5), build(2, 4, 6, 8), true)));
        System.out.println("remove 6: " + show(removeValue(build(6, 6, 1, 6, 2), 6)));
    }
}

