import java.util.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    static ListNode build(int... vals) {
        ListNode dummy = new ListNode(0), tail = dummy;
        for (int v : vals) { tail.next = new ListNode(v); tail = tail.next; }
        return dummy.next;
    }

    static ListNode nodeAt(ListNode head, int index) {
        while (index-- > 0) head = head.next;
        return head;
    }

    static String show(ListNode head) {
        StringBuilder sb = new StringBuilder();
        for (ListNode n = head; n != null; n = n.next) {
            if (sb.length() > 0) sb.append(" -> ");
            sb.append(n.val);
        }
        return sb.length() == 0 ? "(empty)" : sb.toString();
    }

    static boolean hasCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) return true;
    }
    return false;
}

// Returns the node where the cycle starts, or null. Prints a trace if asked.
static ListNode detectCycle(ListNode head, boolean trace) {
    ListNode slow = head, fast = head;
    int step = 0;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (trace) System.out.println(++step + " | slow=" + slow.val + " fast=" + fast.val);
        if (slow == fast) {
            ListNode p = head;                 // phase 2: restart one pointer from head
            int walk = 0;
            while (p != slow) {
                p = p.next; slow = slow.next;
                walk++;
                if (trace)
                    System.out.println("p" + walk + " | p=" + p.val + " slow=" + slow.val);
            }
            return p;
        }
    }
    return null;
}

static ListNode middle(ListNode head) {        // second middle when length is even
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }
    return slow;
}

static ListNode reverse(ListNode head) {
    ListNode prev = null;
    while (head != null) {
        ListNode nxt = head.next;
        head.next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

static boolean isPalindrome(ListNode head) {
    if (head == null || head.next == null) return true;
    ListNode slow = head, fast = head;
    while (fast.next != null && fast.next.next != null) {   // first middle
        slow = slow.next;
        fast = fast.next.next;
    }
    ListNode second = reverse(slow.next);
    ListNode a = head, b = second;
    boolean ok = true;
    while (b != null) {
        if (a.val != b.val) { ok = false; break; }
        a = a.next; b = b.next;
    }
    slow.next = reverse(second);                            // restore the list
    return ok;
}

static int digitSquareSum(int n) {
    int sum = 0;
    while (n > 0) { int d = n % 10; sum += d * d; n /= 10; }
    return sum;
}
    static boolean isHappy(int n) {
        int slow = n, fast = digitSquareSum(n);
        while (fast != 1 && slow != fast) {
            slow = digitSquareSum(slow);
            fast = digitSquareSum(digitSquareSum(fast));
        }
        return fast == 1;
    }

    static ListNode removeNthFromEnd(ListNode head, int n) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode lead = dummy, lag = dummy;
        for (int i = 0; i < n; i++) lead = lead.next;           // open a gap of n nodes
        while (lead.next != null) { lead = lead.next; lag = lag.next; }
        lag.next = lag.next.next;                               // lag sits just before the target
        return dummy.next;
    }

    static ListNode getIntersection(ListNode a, ListNode b) {
        ListNode p = a, q = b;
        while (p != q) {
            p = (p == null) ? b : p.next;
            q = (q == null) ? a : q.next;
        }
        return p;                                               // meeting node, or null
    }

    // LeetCode 287: array as a linked list i -> nums[i]
    static int findDuplicate(int[] nums) {
        int slow = nums[0], fast = nums[0];
        do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast);
        slow = nums[0];
        while (slow != fast) { slow = nums[slow]; fast = nums[fast]; }
        return slow;
    }

