import java.util.*;

public class Main {
    static boolean isValid(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '(' -> stack.push(')');
                case '[' -> stack.push(']');
                case '{' -> stack.push('}');
                default -> {
                    if (stack.isEmpty() || stack.pop() != c) return false;
                }
            }
        }
        return stack.isEmpty();
    }

    static class MinStack {
        private final Deque<int[]> stack = new ArrayDeque<>();   // {value, min so far}
        void push(int x) {
            int min = stack.isEmpty() ? x : Math.min(x, stack.peek()[1]);
            stack.push(new int[]{x, min});
        }
        void pop() { stack.pop(); }
        int top() { return stack.peek()[0]; }
        int getMin() { return stack.peek()[1]; }
    }

    static int evalRPN(String[] tokens) {
        Deque<Integer> st = new ArrayDeque<>();
        for (String t : tokens) {
            switch (t) {
                case "+" -> st.push(st.pop() + st.pop());
                case "*" -> st.push(st.pop() * st.pop());
                case "-" -> { int b = st.pop(), a = st.pop(); st.push(a - b); }
                case "/" -> { int b = st.pop(), a = st.pop(); st.push(a / b); }
                default -> st.push(Integer.parseInt(t));
            }
        }
        return st.pop();
    }

    static String decodeString(String s, boolean trace) {
        Deque<Integer> counts = new ArrayDeque<>();
        Deque<StringBuilder> prefixes = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        int k = 0, step = 0;
        for (char c : s.toCharArray()) {
            String action;
            if (Character.isDigit(c)) {
                k = k * 10 + (c - '0');
                action = "build number";
            } else if (c == '[') {
            counts.push(k); prefixes.push(cur);
            cur = new StringBuilder(); k = 0;
            action = "push count and text, reset";
        } else if (c == ']') {
            int times = counts.pop();
            StringBuilder prev = prefixes.pop();
            prev.append(String.valueOf(cur).repeat(times));
            cur = prev;
            action = "pop, repeat " + times + " times";
        } else {
            cur.append(c);
            action = "append letter";
        }
        if (trace) System.out.println(++step + " | '" + c + "' | cur=\"" + cur + "\" k=" + k
            + " counts=" + counts + " prefixes=" + prefixes + " | " + action);
    }
    return cur.toString();
}

static boolean backspaceCompare(String s, String t) {
    return build(s).equals(build(t));
}
private static String build(String s) {
    StringBuilder sb = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (c != '#') sb.append(c);
        else if (sb.length() > 0) sb.setLength(sb.length() - 1);
    }
    return sb.toString();
}

static String simplifyPath(String path) {
    Deque<String> stack = new ArrayDeque<>();
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) { if (!stack.isEmpty()) stack.pop(); }
        else stack.push(part);
    }
    if (stack.isEmpty()) return "/";
    StringBuilder sb = new StringBuilder();
    Iterator<String> it = stack.descendingIterator();   // bottom of the stack first
    while (it.hasNext()) sb.append('/').append(it.next());
    return sb.toString();
}

// Explicit stack imitating recursion: iterative DFS preorder on a tiny tree
record Node(int val, Node left, Node right) {}
static List<Integer> preorder(Node root) {
    List<Integer> out = new ArrayList<>();
    Deque<Node> stack = new ArrayDeque<>();
    if (root != null) stack.push(root);
    while (!stack.isEmpty()) {
        Node n = stack.pop();
        out.add(n.val());
        if (n.right() != null) stack.push(n.right());
        if (n.left() != null) stack.push(n.left());
    }
    return out;
}

