import java.util.*;

public class Main {
    // Days until a warmer temperature. Stack holds indices with decreasing temperatures.
    static int[] dailyTemperatures(int[] t, boolean trace) {
        int n = t.length;
        int[] ans = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            StringBuilder popped = new StringBuilder();
            while (!stack.isEmpty() && t[stack.peek()] < t[i]) {
                int j = stack.pop();
                ans[j] = i - j;
                popped.append("pop ").append(j).append(" (ans=").append(i - j).append(") ");
            }
            stack.push(i);
            if (trace) System.out.println(i + " | t=" + t[i] + " | " + (popped.length() == 0
                ? "no pop " : popped) + "| stack (top first)=" + stack);
        }
        return ans;
    }

    // Next greater element in a circular array: walk the array twice
    static int[] nextGreaterCircular(int[] a) {
        int n = a.length;
        int[] res = new int[n];
        Arrays.fill(res, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < 2 * n; i++) {
            int x = a[i % n];
            while (!st.isEmpty() && a[st.peek()] < x) res[st.pop()] = x;
            if (i < n) st.push(i);
        }
        return res;
    }

    // Largest rectangle in a histogram; a sentinel height 0 at the end flushes the stack
    static int largestRectangle(int[] h, boolean trace) {
        Deque<Integer> st = new ArrayDeque<>();
        int best = 0;
        for (int i = 0; i <= h.length; i++) {
            int cur = (i == h.length) ? 0 : h[i];
            while (!st.isEmpty() && h[st.peek()] > cur) {
                int height = h[st.pop()];
                int left = st.isEmpty() ? -1 : st.peek();
                int width = i - left - 1;
            int area = height * width;
            if (trace) System.out.println("i=" + i + " cur=" + cur + " | pop height " + height
                + " width " + width + " area " + area);
            best = Math.max(best, area);
        }
        st.push(i);
    }
    return best;
}

static int trapStack(int[] h) {
    Deque<Integer> st = new ArrayDeque<>();
    int water = 0;
    for (int i = 0; i < h.length; i++) {
        while (!st.isEmpty() && h[st.peek()] < h[i]) {
            int bottom = h[st.pop()];
            if (st.isEmpty()) break;
            int left = st.peek();
            int width = i - left - 1;
            int bounded = Math.min(h[left], h[i]) - bottom;
            water += width * bounded;
        }
        st.push(i);
    }
    return water;
}

static int trapTwoPointers(int[] h) {
    int l = 0, r = h.length - 1, lmax = 0, rmax = 0, water = 0;
    while (l < r) {
        if (h[l] < h[r]) {
            lmax = Math.max(lmax, h[l]);
            water += lmax - h[l++];
        } else {
            rmax = Math.max(rmax, h[r]);
            water += rmax - h[r--];
        }
    }
    return water;
}

