import java.util.*;

public class Main {
    // Queue using two stacks: amortised O(1) per operation
    static class MyQueue {
        private final Deque<Integer> in = new ArrayDeque<>(), out = new ArrayDeque<>();
        void push(int x) { in.push(x); }
        int pop() { move(); return out.pop(); }
        int peek() { move(); return out.peek(); }
        boolean empty() { return in.isEmpty() && out.isEmpty(); }
        private void move() {
            if (out.isEmpty()) while (!in.isEmpty()) out.push(in.pop());
        }
    }

    // Circular queue on a fixed array: head index + size
    static class MyCircularQueue {
        private final int[] data;
        private int head = 0, size = 0;
        MyCircularQueue(int k) { data = new int[k]; }
        boolean enQueue(int v) {
        if (isFull()) return false;
        data[(head + size) % data.length] = v;
        size++;
        return true;
    }
    boolean deQueue() {
        if (isEmpty()) return false;
        head = (head + 1) % data.length;
        size--;
        return true;
    }
    int Front() { return isEmpty() ? -1 : data[head]; }
    int Rear() { return isEmpty() ? -1 : data[(head + size - 1) % data.length]; }
    boolean isEmpty() { return size == 0; }
    boolean isFull() { return size == data.length; }
}

// Sliding window maximum: deque of indices, values decreasing front to back
static int[] maxSlidingWindow(int[] nums, int k, boolean trace) {
    int n = nums.length;
    int[] res = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();       // expired
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast(); // dominated
        dq.offerLast(i);
        if (i >= k - 1) res[i - k + 1] = nums[dq.peekFirst()];
        if (trace) {
            List<Integer> vals = new ArrayList<>();
            for (int idx : dq) vals.add(nums[idx]);
            System.out.println(i + " | add " + nums[i] + " | deque indices=" + dq
                + " values=" + vals + " | " + (i >= k - 1
                ? "max=" + nums[dq.peekFirst()] : "window not full"));
        }
    }
    return res;
}

static int[] maxSlidingBrute(int[] nums, int k) {
    int[] res = new int[nums.length - k + 1];
    for (int i = 0; i < res.length; i++) {
        int m = Integer.MIN_VALUE;
        for (int j = i; j < i + k; j++) m = Math.max(m, nums[j]);
        res[i] = m;
    }
    return res;
}

// LRU cache, the short way: LinkedHashMap in access order
static class LRUCacheShort<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;
    LRUCacheShort(int capacity) {
        super(16, 0.75f, true);          // true = access order
        this.capacity = capacity;
    }
    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;
    }
}

// LRU cache by hand: HashMap + doubly linked list with sentinels
static class LRUCache {
    private static class Node {
        int key, val;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(0, 0), tail = new Node(0, 0);   // sentinels

    LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }
    int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n);
        addFront(n);                       // most recently used sits next to head
        return n.val;
    }
    void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) {
            n.val = value;
            unlink(n);
            addFront(n);
            return;
        }
        if (map.size() == capacity) {
            Node lru = tail.prev;          // least recently used sits next to tail
            unlink(lru);
            map.remove(lru.key);
        }
        n = new Node(key, value);
        map.put(key, n);
        addFront(n);
    }
    private void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFront(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    String order() {                       // most recent first
        StringBuilder sb = new StringBuilder();
        for (Node n = head.next; n != tail; n = n.next) sb.append(n.key).append(' ');
        return sb.toString().trim();
    }
}

// BFS preview: fewest moves on a tiny grid ('#' is a wall)
static int shortestPath(String[] grid) {
    int rows = grid.length, cols = grid[0].length();
    boolean[][] seen = new boolean[rows][cols];
    Deque<int[]> q = new ArrayDeque<>();
    q.offer(new int[]{0, 0});
    seen[0][0] = true;
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int dist = 0;
    while (!q.isEmpty()) {
        for (int sz = q.size(); sz > 0; sz--) {          // one level = one distance
            int[] cur = q.poll();
            if (cur[0] == rows - 1 && cur[1] == cols - 1) return dist;
            for (int[] d : dirs) {
                int r = cur[0] + d[0], c = cur[1] + d[1];
                if (r < 0 || c < 0 || r >= rows || c >= cols) continue;
                if (seen[r][c] || grid[r].charAt(c) == '#') continue;
                seen[r][c] = true;
                q.offer(new int[]{r, c});
            }
        }
        dist++;
    }
    return -1;
}

